// Auto-generated by HARVEST agent_runner - do not edit.
//
// Post-compaction recovery of the rules and the state file. After a compaction, the model's only
// fresh user input is a generic synthetic "Continue if you have next
// steps..." message, with no sign that a compaction happened. This plugin
// replaces that message with an instruction to read these files again, and
// asks the summary to end with the same instruction. The hooks run in every
// session, sub-agents included, so the text tells the main agent and a
// sub-agent apart.
//
// Appends to `compaction_recovery.log` in the work dir so runs can verify the
// hooks actually fired.
import fs from "node:fs"

const SUBAGENT_TEXT =
  "If you are a sub-agent, read again the prompt file that your task message " +
  "names, and `inputs/prompts/subagent.md`."

const RECOVERY_TEXT =
  "A context compaction just occurred: the conversation above was replaced " +
  "by a summary. FIRST ACTIONS (mandatory): If you are the main agent of the " +
  "stage, run these commands, in this order, to restore your rules and your " +
  "working memory: {RECOVERY_CMDS}. " + SUBAGENT_TEXT +
  " Then continue with your own task."

const logged = new Set()
function log(key, line) {
  if (logged.has(key)) return
  logged.add(key)
  try {
    fs.appendFileSync("compaction_recovery.log", new Date().toISOString() + " " + line + "\n")
  } catch {}
}

export const CompactionRecovery = async () => ({
  "experimental.session.compacting": async (_input, output) => {
    output.context.push(
      "The summary MUST state whether this agent is the main agent of the " +
        "stage or a sub-agent, and the prompt file that its task message names. " +
        "The summary MUST end with a section titled 'MANDATORY FIRST ACTIONS'. " +
        "It states: If you are the main agent of the stage, run these commands, " +
        "in this order, before doing anything else: {RECOVERY_CMDS}. " +
        SUBAGENT_TEXT + " Then continue with your own task.",
    )
    log("compacting:" + Date.now(), "compacting hook fired")
  },
  "experimental.chat.messages.transform": async (_input, output) => {
    for (const msg of output.messages) {
      if (msg.info.role !== "user") continue
      for (const part of msg.parts) {
        if (part.type !== "text" || typeof part.text !== "string") continue
        const marked = part.metadata && part.metadata.compaction_continue === true
        // Fallback for when the metadata marker is missing.
        const fallback =
          part.synthetic === true && part.text.startsWith("Continue if you have next steps")
        if (marked || fallback) {
          part.text = RECOVERY_TEXT
          log("rewrite:" + part.id, "rewrote compaction continue message " + part.id)
        }
      }
    }
  },
})
